def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if np_array.ndim != 2:
        raise ValueError("Input must be a 2D array")
    rows, cols = np_array.shape
    matrix = _gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            val = np_array[i, j]
            ctypes.memmove(ctypes.c_void_p(ctypes.addressof(matrix.contents.data[i*cols + j])), ctypes.c_double(val), 1)
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix):
