import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = np.array(matrix, dtype=np.float64, order='F')
        self.size = len(matrix)
        self.ptr = ctypes.pointer(ctypes.c_double * self.size)(self.matrix)

    @staticmethod
    def is_positive_definite(matrix):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_matrix_chol_update.restype = ctypes.c_int
        mat = GSLMatrix(matrix)
        status = gsl.gsl_matrix_chol_update(mat.ptr, mat.size)
        return status == 0

    @staticmethod
    def cholesky_decomp(matrix):
        if not GSLMatrix.is_positive_definite(matrix):
            raise ValueError("Matrix is not positive definite.")

        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl_gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl_gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
        gsl_gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

        mat = GSLMatrix(matrix)
        result = (ctypes.c_double * mat.size)()
        status = gsl_gsl.gsl_linalg_cholesky_decomp(result, mat.size)
        if status != 0:
            raise RuntimeError("Cholesky decomposition failed.")

        lower_triangular = [[0.0 for _ in range(mat.size)] for _ in range(mat.size)]
        for i in range(mat.size):
            for j in range(i + 1):
                lower_triangular[i][j] = result[i * mat.size + j]
        return lower_triangular

